/**
 * src/editor/linter-logic.js
 * Static LaTeX analysis and linting:
 * - Undefined control sequences based on loaded packages & local definitions
 * - Nearest command suggestion (Levenshtein distance <= 2)
 * - Mismatched \begin{env} and \end{env}
 * - Unbalanced braces
 */

const fs = require('fs');
const path = require('path');

// Load database generated by scripts/build-latex-db.js
let COMMANDS_DB = null;
function getCommandsDb() {
  if (!COMMANDS_DB) {
    try {
      const dbPath = path.join(__dirname, '../../data/latex-commands.json');
      if (fs.existsSync(dbPath)) {
        COMMANDS_DB = JSON.parse(fs.readFileSync(dbPath, 'utf8'));
      }
    } catch (e) {
      console.warn('Could not load latex-commands.json:', e.message);
    }
    if (!COMMANDS_DB) {
      COMMANDS_DB = { macros: [], environments: [], packages: [] };
    }
  }
  return COMMANDS_DB;
}

// Levenshtein distance helper
function levenshteinDistance(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;

  const matrix = [];
  for (let i = 0; i <= b.length; i++) matrix[i] = [i];
  for (let j = 0; j <= a.length; j++) matrix[0][j] = j;

  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1, // substitution
          matrix[i][j - 1] + 1,     // insertion
          matrix[i - 1][j] + 1      // deletion
        );
      }
    }
  }
  return matrix[b.length][a.length];
}

/**
 * Extracts all loaded packages and document class from LaTeX text.
 */
function extractLoadedPackages(text) {
  const packages = new Set(['latex2e']);

  // Document class e.g. \documentclass[11pt]{article} or beamer
  const docClassMatch = text.match(/\\documentclass(?:\[[^\]]*\])?\{([^}]+)\}/);
  if (docClassMatch) {
    const cls = docClassMatch[1].trim();
    packages.add(cls);
    if (cls === 'beamer') packages.add('beamer');
    if (cls === 'amsart' || cls === 'amsbook') {
      packages.add('amsmath');
      packages.add('amssymb');
      packages.add('amsthm');
    }
  }

  // \usepackage[...]{pkg1, pkg2}
  const usepkgRegex = /\\usepackage(?:\[[^\]]*\])?\{([^}]+)\}/g;
  let m;
  while ((m = usepkgRegex.exec(text)) !== null) {
    const rawPkgs = m[1].split(',');
    for (let p of rawPkgs) {
      p = p.trim();
      if (p) packages.add(p);
    }
  }

  return packages;
}

/**
 * Extracts locally defined commands and environments:
 * \newcommand{\mycmd}, \def\mycmd, \DeclareMathOperator{\op}, etc.
 */
function extractLocalDefinitions(text, extraStyContent = '') {
  const localCommands = new Set();
  const localEnvironments = new Set();

  const combined = text + '\n' + extraStyContent;

  // \newcommand{\name}, \renewcommand{\name}, \providecommand{\name}
  const newcmdRegex = /\\(?:re|provide)?newcommand\*?\{?\\([a-zA-Z@]+)\}?/g;
  let m;
  while ((m = newcmdRegex.exec(combined)) !== null) {
    localCommands.add(m[1]);
  }

  // \def\name
  const defRegex = /\\def\\([a-zA-Z@]+)/g;
  while ((m = defRegex.exec(combined)) !== null) {
    localCommands.add(m[1]);
  }

  // \let\new=\old
  const letRegex = /\\let\\([a-zA-Z@]+)/g;
  while ((m = letRegex.exec(combined)) !== null) {
    localCommands.add(m[1]);
  }

  // \DeclareMathOperator{\op}{...}
  const opRegex = /\\DeclareMathOperator\*?\{?\\([a-zA-Z@]+)\}?/g;
  while ((m = opRegex.exec(combined)) !== null) {
    localCommands.add(m[1]);
  }

  // \newenvironment{name}
  const newenvRegex = /\\newenvironment\*?\{([a-zA-Z0-9*_-]+)\}/g;
  while ((m = newenvRegex.exec(combined)) !== null) {
    localEnvironments.add(m[1]);
  }

  return { localCommands, localEnvironments };
}

/**
 * Runs the static diagnostic checks on a LaTeX document.
 * Returns an array of diagnostics compatible with CodeMirror 6 Lint:
 * { from, to, severity, message, line, actions: [{ name, apply }] }
 */
function lintLatexDocument(text, options = {}) {
  const diagnostics = [];
  if (!text || typeof text !== 'string') return diagnostics;

  const db = getCommandsDb();
  const loadedPackages = extractLoadedPackages(text);
  const { localCommands, localEnvironments } = extractLocalDefinitions(text, options.extraStyContent || '');

  // Build the set of valid commands and environments
  const validCommands = new Set(localCommands);
  const validEnvironments = new Set(localEnvironments);
  const knownCommandNames = [];

  // Always include standard primitive/core commands
  validCommands.add('begin');
  validCommands.add('end');
  validCommands.add('item');
  validCommands.add('label');
  validCommands.add('ref');
  validCommands.add('cite');
  validCommands.add('documentclass');
  validCommands.add('usepackage');

  for (const macro of db.macros) {
    knownCommandNames.push(macro.name);
    // Active if in core or loaded package
    if (macro.package === 'latex2e' || loadedPackages.has(macro.package)) {
      validCommands.add(macro.name);
    }
  }

  for (const env of db.environments) {
    if (env.package === 'latex2e' || loadedPackages.has(env.package)) {
      validEnvironments.add(env.name);
    }
  }

  // Pre-calculate line start offsets for l.<line> reporting
  const lines = text.split('\n');
  const lineStarts = [0];
  for (let i = 0; i < lines.length - 1; i++) {
    lineStarts.push(lineStarts[i] + lines[i].length + 1);
  }
  function getLineNumber(offset) {
    let low = 0, high = lineStarts.length - 1;
    while (low <= high) {
      const mid = (low + high) >> 1;
      if (lineStarts[mid] <= offset) {
        if (mid === lineStarts.length - 1 || lineStarts[mid + 1] > offset) return mid + 1;
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    return 1;
  }

  // Mask regions: comments and verbatim
  const len = text.length;
  const isMasked = new Uint8Array(len);

  // Mask % comments
  for (let i = 0; i < len; i++) {
    if (text[i] === '%') {
      let bs = 0, j = i - 1;
      while (j >= 0 && text[j] === '\\') { bs++; j--; }
      if (bs % 2 === 0) {
        while (i < len && text[i] !== '\n') { isMasked[i] = 1; i++; }
      }
    }
  }

  // Mask verbatim blocks
  const verbEnvRegex = /\\begin\{(?:verbatim|lstlisting|minted)\}[\s\S]*?\\end\{(?:verbatim|lstlisting|minted)\}/g;
  let vm;
  while ((vm = verbEnvRegex.exec(text)) !== null) {
    for (let k = vm.index; k < vm.index + vm[0].length; k++) isMasked[k] = 1;
  }

  // 1. Check commands: \\[a-zA-Z@]+\*?
  const cmdRegex = /\\([a-zA-Z@]+)\*?/g;
  let cm;
  while ((cm = cmdRegex.exec(text)) !== null) {
    const from = cm.index;
    const to = from + cm[0].length;
    if (isMasked[from]) continue;

    const cmdName = cm[1];
    // Skip definition commands themselves
    if (cmdName === 'newcommand' || cmdName === 'renewcommand' || cmdName === 'providecommand' || cmdName === 'def') {
      continue;
    }

    if (!validCommands.has(cmdName)) {
      const lineNum = getLineNumber(from);
      // Find nearest known command (Levenshtein <= 2)
      let bestMatch = null;
      let minDistance = 3;

      for (const known of knownCommandNames) {
        const d = levenshteinDistance(cmdName, known);
        if (d < minDistance) {
          minDistance = d;
          bestMatch = known;
          if (d === 1) break;
        }
      }

      const actions = [];
      let fixNotice = '';
      if (bestMatch && minDistance <= 2) {
        actions.push({
          name: `Did you mean \\${bestMatch}?`,
          apply(view, fromOffset, toOffset) {
            view.dispatch({ changes: { from: fromOffset, to: toOffset, insert: `\\${bestMatch}` } });
          }
        });
        fixNotice = ` Did you mean \\${bestMatch}?`;
      }

      diagnostics.push({
        from: from,
        to: to,
        severity: 'error',
        line: lineNum,
        message: `! Undefined control sequence. l.${lineNum} \\${cmdName}.${fixNotice}`,
        actions: actions
      });
    }
  }

  // 2. Check matched \begin{env} and \end{env}
  const envStack = [];
  const envTagRegex = /\\(begin|end)\{([a-zA-Z0-9*_-]+)\}/g;
  let em;
  while ((em = envTagRegex.exec(text)) !== null) {
    const from = em.index;
    const to = from + em[0].length;
    if (isMasked[from]) continue;

    const kind = em[1];
    const envName = em[2];
    const lineNum = getLineNumber(from);

    if (kind === 'begin') {
      envStack.push({ name: envName, from, to, line: lineNum });
    } else {
      if (envStack.length === 0) {
        diagnostics.push({
          from: from,
          to: to,
          severity: 'error',
          line: lineNum,
          message: `! LaTeX Error: \\end{${envName}} without matching \\begin{${envName}}.`
        });
      } else {
        const last = envStack.pop();
        if (last.name !== envName) {
          diagnostics.push({
            from: from,
            to: to,
            severity: 'error',
            line: lineNum,
            message: `! LaTeX Error: \\begin{${last.name}} on line ${last.line} ended by \\end{${envName}} on line ${lineNum}.`
          });
        }
      }
    }
  }

  // Unclosed \begin{env} remaining on stack
  for (const unclosed of envStack) {
    diagnostics.push({
      from: unclosed.from,
      to: unclosed.to,
      severity: 'error',
      line: unclosed.line,
      message: `! LaTeX Error: \\begin{${unclosed.name}} on line ${unclosed.line} not closed.`
    });
  }

  // 3. Unbalanced braces outside comments/verbatim
  let braceDepth = 0;
  let lastOpenBracePos = 0;
  for (let i = 0; i < len; i++) {
    if (isMasked[i]) continue;
    if (text[i] === '{') {
      let bs = 0, j = i - 1;
      while (j >= 0 && text[j] === '\\') { bs++; j--; }
      if (bs % 2 === 0) {
        braceDepth++;
        lastOpenBracePos = i;
      }
    } else if (text[i] === '}') {
      let bs = 0, j = i - 1;
      while (j >= 0 && text[j] === '\\') { bs++; j--; }
      if (bs % 2 === 0) {
        braceDepth--;
        if (braceDepth < 0) {
          const lineNum = getLineNumber(i);
          diagnostics.push({
            from: i,
            to: i + 1,
            severity: 'error',
            line: lineNum,
            message: `! Extra }, or forgotten \\endgroup on line ${lineNum}.`
          });
          braceDepth = 0;
        }
      }
    }
  }

  if (braceDepth > 0) {
    const lineNum = getLineNumber(lastOpenBracePos);
    diagnostics.push({
      from: lastOpenBracePos,
      to: lastOpenBracePos + 1,
      severity: 'error',
      line: lineNum,
      message: `! Missing } inserted for brace opened on line ${lineNum}.`
    });
  }

  return diagnostics;
}

module.exports = {
  lintLatexDocument,
  extractLoadedPackages,
  extractLocalDefinitions,
  levenshteinDistance
};
